#pragma once
#include "guest_resource_detours.h"
#include "resource_leaf_profile.h"
namespace BbExtraHeaps {
using namespace BbArmHooks;
constexpr std::array<U,5> GameOffsets={0x2088030,0x2088900,0x2089620,0x20898c0,0x208a400};
constexpr std::array<U,5> FixtureOffsets={0x3000,0x3100,0x3200,0x3300,0x3400};
constexpr std::array<B,6> Prefix={0x55,0x48,0x89,0xe5,0x41,0x57};
constexpr size_t ProfileBytes=1024;
constexpr std::array<std::array<B,32>,5> Digests={{{0xe9,0xc3,0xff,0xe8,0x22,0x5a,0xdd,0x52,0x15,0x11,0x76,0xfe,0xee,0xbb,0xb8,0xb8,0xf,0x96,0x3e,0x33,0xc6,0x48,0x86,0xb5,0x92,0x3f,0x23,0x1e,0x1f,0x27,0x9f,0xe0},{0xa8,0xe9,0x88,0x2a,0x19,0x21,0x1,0x5c,0xba,0xee,0xed,0x26,0xc2,0x9b,0xaf,0x9b,0x9c,0x64,0xa3,0x2,0x72,0x33,0xe4,0x17,0xb9,0xe5,0x94,0xf7,0x2c,0x62,0x84,0x6a},{0x32,0xff,0x2a,0xda,0xc7,0x1b,0x3a,0xfb,0x33,0x95,0x75,0xf8,0x45,0xc7,0xc3,0x10,0xbf,0xa,0xb8,0xf3,0x73,0x6f,0x10,0x93,0x1e,0x7a,0x4b,0x6b,0x57,0xd,0xf6,0x36},{0xbb,0x15,0xda,0xbf,0x18,0xf5,0x9b,0xd1,0x0,0xb0,0x12,0xf5,0x89,0x8f,0x94,0xcb,0xf0,0x3c,0x41,0xc3,0xa1,0x28,0xc0,0xf9,0xfb,0x5d,0xce,0x1e,0xe6,0x65,0x19,0xf3},{0x66,0xb9,0x9,0x8a,0x88,0x3e,0x7a,0xfd,0x8,0x6,0x1d,0xb5,0xdf,0xf5,0xcb,0x88,0x76,0x16,0xb5,0x9c,0x76,0x7e,0x9a,0x16,0xba,0x49,0xa5,0xae,0x70,0x25,0x6,0xb3}}};
inline void ValidateProfiles(std::span<const B> image){
 for(size_t i=0;i<GameOffsets.size();++i){const U at=GameOffsets[i];Require(at<=image.size()&&ProfileBytes<=image.size()-at,"extra heap profile outside image");Require(MatchCodeDigest(image.subspan(at,ProfileBytes),Digests[i]),"extra heap profile mismatch");}
}
inline Plan Prepare(std::span<const B> image,U base,U stub,size_t capacity,const std::array<U,5>& sites,const std::array<U,3>& targets){
 Require(base&&image.size()<=UINT64_MAX-base&&stub&&capacity<=UINT64_MAX-stub,"extra heap address overflow");Require(stub>=base+image.size()||base>=stub+capacity,"extra heap stub overlaps image");for(U target:targets)Require(target,"extra heap missing adapter");
 for(size_t i=0;i<sites.size();++i){const U at=sites[i];Require(at<=image.size()&&Prefix.size()<=image.size()-at&&!memcmp(image.data()+at,Prefix.data(),Prefix.size()),"extra heap original mismatch");for(size_t j=0;j<i;++j)Require(at+Prefix.size()<=sites[j]||sites[j]+Prefix.size()<=at,"extra heap sites overlap");}
 Plan plan;
 const auto place=[&](Emitter& e){size_t size=(e.code.size()+15)&~size_t(15);Require(plan.stubs.size()<=capacity&&size<=capacity-plan.stubs.size(),"extra heap stub capacity");U at=stub+plan.stubs.size();plan.stubs.insert(plan.stubs.end(),e.code.begin(),e.code.end());plan.stubs.resize(plan.stubs.size()+size-e.code.size(),0x90);return at;};
 const auto jump=[&](Emitter& e,U target){U next=stub+plan.stubs.size()+e.code.size()+5;e.Bytes({0xe9});e.Value(Relative(next,target));};
 for(unsigned index=0;index<sites.size();++index){
  Emitter e;e.code.insert(e.code.end(),Prefix.begin(),Prefix.end());jump(e,base+sites[index]+Prefix.size());const U original=place(e);e=Emitter{};
  const bool free=index==1||index==4;
  const auto bypass=[&](B condition){U next=stub+plan.stubs.size()+e.code.size()+6;e.Bytes({0x0f,condition});e.Value(Relative(next,original));};
  if(index==3){e.Bytes({0x48,0x83,0xfa,0x10});bypass(0x86);} // original small-alignment tail reaches the hooked plain entry
  if(!free){
   // Preserve the original arguments across a real guest call; no native->FEX
   // round trip and no allocation replay. Three pushes retain SysV alignment.
   e.Bytes({0x57,0x56,0x52});U next=stub+plan.stubs.size()+e.code.size()+5;e.Bytes({0xe8});e.Value(Relative(next,original));e.Bytes({0x5a,0x5e,0x5f});
   std::array<size_t,2> done{};const auto finish=[&](B condition,unsigned i){e.Bytes({0x0f,condition});done[i]=e.code.size();e.Value(uint32_t(0));};
   e.Bytes({0x49,0xba});e.Value(U(0x7000000000));e.Bytes({0x4c,0x39,0xd0});finish(0x82,0);e.Bytes({0x49,0xba});e.Value(U(0xf000000000));e.Bytes({0x4c,0x39,0xd0});finish(0x83,1);
   e.Bytes({0x48,0x89,0xc1,0x41,0xb8});e.Value(uint32_t(index));e.JumpAbs(targets[0]);const size_t at=e.code.size();e.Bytes({0xc3});for(size_t patch:done){int32_t d=at-patch-4;memcpy(e.code.data()+patch,&d,4);}
  }else{
   // CPU-only frees execute the original body without a host transition.
   e.Bytes({0x49,0xba});e.Value(U(0x7000000000));e.Bytes({0x4c,0x39,0xd6});bypass(0x82);e.Bytes({0x49,0xba});e.Value(U(0xf000000000));e.Bytes({0x4c,0x39,0xd6});bypass(0x83);
   e.Bytes({0x41,0x54,0x48,0x83,0xec,0x20,0x49,0x89,0xe4,0x49,0x89,0x3c,0x24,0x49,0x89,0x74,0x24,0x08,0xba});e.Value(uint32_t(index));e.CallAbs(targets[1]);
   e.Bytes({0x49,0x89,0x44,0x24,0x10,0x49,0x8b,0x3c,0x24,0x49,0x8b,0x74,0x24,0x08});U next=stub+plan.stubs.size()+e.code.size()+5;e.Bytes({0xe8});e.Value(Relative(next,original));
   // Protect the original free's return value/vector state. SaveFull borrows
   // live r12; its first saved word is our wrapper-local frame pointer.
   e.SaveFull();e.Bytes({0x49,0x8b,0x04,0x24,0x48,0x8b,0x78,0x08,0x48,0x8b,0x70,0x10,0xba});e.Value(uint32_t(index));e.CallAbs(targets[2]);e.RestoreFull();
   e.Bytes({0x4c,0x89,0xe4,0x48,0x83,0xc4,0x20,0x41,0x5c,0xc3});
  }
  U target=place(e);std::vector<B> bytes(Prefix.size(),0x90);bytes[0]=0xe9;auto delta=Relative(base+sites[index]+5,target);memcpy(bytes.data()+1,&delta,4);plan.patches.push_back({sites[index],std::move(bytes)});
 }
 return plan;
}
}
